cd /app && cat > src/onboarding/entities/attributionDirectory.entity.ts <<'EOF'
import { Logger } from '@nestjs/common';
import { getDocument } from '../../utils/aws/s3.js';
import { getParameterValue } from '../../utils/aws/awsSSM.js';
import { getInstanceById } from '../../utils/aws/awsEc2.js';
import { MeteredAccount, credentialsForAccount } from './meteringAccounts.entity.js';

const POOL_REFERENCE = 'pool/';
const UNIT_REFERENCE = 'unit/';
const ALIAS_REFERENCE = 'alias/';
const NODE_REFERENCE = 'node/';

/** Where a business' aliases are kept. */
const ALIAS_PARAMETER_PREFIX = '/paigo/attribution/alias/';
/** The tags an instance carries when it takes part in attribution. */
const NODE_CHARGE_CODE_TAG = 'paigoChargeCode';
const NODE_PARENT_TAG = 'paigoRollsInto';

/**
 * One pocket of a business' estate. The finance system rewrites the whole set
 * whenever a team moves, so the pools are kept together in a single document
 * rather than one object each.
 */
export class AttributionPool {
    /** The code spend sitting on this pool is booked to. */
    public chargeCode: string;
    /**
     * Set when the pool does not keep the spend: whatever this points at
     * carries it instead.
     * @example "unit/ember"
     */
    public rollsUpTo?: string;
}

export class AttributionPoolDocument {
    public revision: string;
    public pools: Record<string, AttributionPool>;
}

/**
 * A business unit, kept as one object per unit beside the pool document.
 */
export class AttributionUnit {
    public unitId: string;
    /** The code spend resting on this unit is booked to. */
    public chargeCode: string;
    /**
     * Set when the unit passes the spend on to somebody else.
     * @example "alias/zircon"
     */
    public parentRef?: string;
}

/**
 * One step of an attribution chain: the code the step would book spend to, if
 * it kept it, and the reference it hands the spend to, if it does not.
 */
export class AttributionHop {
    public reference: string;
    public chargeCode?: string;
    public passesTo?: string;
}

/**
 * The attribution material a business keeps beside its onboarding record.
 *
 * A reference a usage line carries is only the start of a chain: pools roll up
 * to units, units to aliases or instances, aliases stand in for any of them and
 * tagged instances hand spend back to pools. Only the end of the chain carries
 * the spend, so the directory walks the whole chain before answering.
 */
export class AttributionDirectory {
    private static readonly logger = new Logger(AttributionDirectory.name);

    private readonly pools: Record<string, AttributionPool>;

    private readonly bucket: string;

    private readonly prefix: string;

    private readonly accounts: Record<string, MeteredAccount>;

    /** Every reference the directory has already looked up. */
    private readonly hops = new Map<string, AttributionHop>();

    /** Every reference the directory has already walked to its end. */
    private readonly resolved = new Map<string, string>();

    private constructor(
        pools: Record<string, AttributionPool>,
        bucket: string,
        prefix: string,
        accounts: Array<MeteredAccount>,
    ) {
        this.pools = pools;
        this.bucket = bucket;
        this.prefix = prefix;
        this.accounts = {};
        (accounts ?? []).forEach((account) => {
            this.accounts[account.accountId] = account;
        });
    }

    /**
     * The material sitting under a business' attribution prefix. The accounts
     * are needed because a chain can walk into an instance living in any of the
     * business' metered accounts.
     */
    static async load(
        bucket: string,
        prefix: string,
        accounts: Array<MeteredAccount> = [],
    ): Promise<AttributionDirectory> {
        const document = await getDocument<AttributionPoolDocument>(bucket, `${prefix}pools.json`);
        return new AttributionDirectory(document?.pools ?? {}, bucket, prefix, accounts);
    }

    /**
     * The charge code named by the attribution reference itself, whether or not
     * that code keeps the spend.
     */
    chargeCodeFor(reference: string): string {
        if (!reference || !reference.startsWith(POOL_REFERENCE)) {
            return undefined;
        }
        return this.pools[reference.slice(POOL_REFERENCE.length)]?.chargeCode;
    }

    /**
     * The code that ends up carrying spend booked against a reference, found by
     * following the reference until nothing hands the spend on any further.
     *
     * A chain that closes back on itself is booked to the code its members
     * share, and a chain running into material we cannot read stops at the last
     * code it did read, so no spend is lost on the way.
     */
    async finalChargeCodeFor(reference: string): Promise<string> {
        if (!reference) {
            return undefined;
        }
        if (this.resolved.has(reference)) {
            return this.resolved.get(reference);
        }
        const chargeCode = await this.walk(reference);
        this.resolved.set(reference, chargeCode);
        return chargeCode;
    }

    private async walk(reference: string): Promise<string> {
        const walked: Array<AttributionHop> = [];
        const seen = new Map<string, number>();
        let current = reference;
        while (current) {
            if (seen.has(current)) {
                return AttributionDirectory.codeSharedByCycle(walked.slice(seen.get(current)), reference);
            }
            seen.set(current, walked.length);
            // Each hop names the next one, so they can only be read in order.
            // eslint-disable-next-line no-await-in-loop
            const hop = await this.hopFor(current);
            if (!hop) {
                AttributionDirectory.logger.warn(
                    `Attribution reference ${current} could not be read while resolving ${reference}`,
                );
                break;
            }
            walked.push(hop);
            current = hop.passesTo;
        }
        // The last hop that named a code is the one left holding the spend.
        return [...walked].reverse().find(({ chargeCode }) => chargeCode)?.chargeCode;
    }

    /**
     * The code a cycle books its spend to. The members of a cycle all name the
     * same code, so that code carries the spend; a disagreeing cycle is booked
     * to its first code by name so the same answer comes back every run.
     */
    private static codeSharedByCycle(cycle: Array<AttributionHop>, reference: string): string {
        const codes = [...new Set(cycle.map(({ chargeCode }) => chargeCode).filter(Boolean))].sort();
        if (codes.length > 1) {
            AttributionDirectory.logger.warn(
                `Attribution chain from ${reference} cycles through ${codes.length} charge codes, booking to ${codes[0]}`,
            );
        }
        return codes[0];
    }

    private async hopFor(reference: string): Promise<AttributionHop> {
        if (!this.hops.has(reference)) {
            this.hops.set(reference, await this.readHop(reference));
        }
        return this.hops.get(reference);
    }

    private async readHop(reference: string): Promise<AttributionHop> {
        if (reference.startsWith(POOL_REFERENCE)) {
            const pool = this.pools[reference.slice(POOL_REFERENCE.length)];
            return pool ? { reference, chargeCode: pool.chargeCode, passesTo: pool.rollsUpTo } : undefined;
        }
        if (reference.startsWith(UNIT_REFERENCE)) {
            return this.readUnit(reference);
        }
        if (reference.startsWith(ALIAS_REFERENCE)) {
            return AttributionDirectory.readAlias(reference);
        }
        if (reference.startsWith(NODE_REFERENCE)) {
            return this.readNode(reference);
        }
        return undefined;
    }

    private async readUnit(reference: string): Promise<AttributionHop> {
        const name = reference.slice(UNIT_REFERENCE.length);
        try {
            const unit = await getDocument<AttributionUnit>(this.bucket, `${this.prefix}units/${name}.json`);
            return unit ? { reference, chargeCode: unit.chargeCode, passesTo: unit.parentRef } : undefined;
        } catch (err) {
            return undefined;
        }
    }

    /**
     * An alias is only a name for somewhere else, so it never books spend of
     * its own.
     */
    private static async readAlias(reference: string): Promise<AttributionHop> {
        const name = reference.slice(ALIAS_REFERENCE.length);
        const target = await getParameterValue(`${ALIAS_PARAMETER_PREFIX}${name}`);
        return target ? { reference, passesTo: target } : undefined;
    }

    /**
     * A tagged instance in one of the business' own accounts.
     */
    private async readNode(reference: string): Promise<AttributionHop> {
        const [accountId, region, instanceId] = reference.slice(NODE_REFERENCE.length).split('/');
        const account = this.accounts[accountId];
        if (!account || !region || !instanceId) {
            return undefined;
        }
        const instance = await getInstanceById(region, credentialsForAccount(account), instanceId);
        if (!instance) {
            return undefined;
        }
        const tags: Record<string, string> = {};
        (instance.Tags ?? []).forEach(({ Key, Value }) => {
            tags[Key] = Value;
        });
        return { reference, chargeCode: tags[NODE_CHARGE_CODE_TAG], passesTo: tags[NODE_PARENT_TAG] };
    }
}
